1	package httpapi
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"net/http"
9		"time"
10	
11		"github.com/cocosolocoder/signalroom/internal/events"
12	)
13	
14	// maxGroupLabels bounds how many label names a preview request may group by.
15	const maxGroupLabels = 4
16	
17	// allowedPreviewFields is the exact set of members POST /alerts/preview
18	// accepts; anything else is an unknown field.
19	var allowedPreviewFields = map[string]struct{}{
20		"since":           {},
21		"until":           {},
22		"window_seconds":  {},
23		"threshold":       {},
24		"trigger_windows": {},
25		"recover_windows": {},
26		"service":         {},
27		"severity":        {},
28		"labels":          {},
29		"group_labels":    {},
30	}
31	
32	type previewResponse struct {
33		GroupLabels []string          `json:"group_labels"`
34		Groups      []previewGroupDTO `json:"groups"`
35	}
36	
37	type previewGroupDTO struct {
38		Service     string          `json:"service"`
39		LabelValues []*string       `json:"label_values"`
40		Windows     []previewWindow `json:"windows"`
41		Alerts      []previewAlert  `json:"alerts"`
42	}
43	
44	type previewWindow struct {
45		Since  string `json:"since"`
46		Until  string `json:"until"`
47		Count  int    `json:"count"`
48		Status string `json:"status"`
49	}
50	
51	type previewAlert struct {
52		TriggeredAt string  `json:"triggered_at"`
53		RecoveredAt *string `json:"recovered_at"`
54	}
55	
56	func (h *Handler) previewAlerts(w http.ResponseWriter, r *http.Request) {
57		if r.Method != http.MethodPost {
58			w.Header().Set("Allow", "POST")
59			writeError(w, http.StatusMethodNotAllowed, "method not allowed")
60			return
61		}
62		if h.unavailable() {
63			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
64			return
65		}
66	
67		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
68		if err != nil {
69			writeError(w, http.StatusBadRequest, "invalid JSON body")
70			return
71		}
72	
73		fields, err := decodeStrictObject(body, allowedPreviewFields)
74		if err != nil {
75			writeError(w, http.StatusBadRequest, "invalid JSON body")
76			return
77		}
78	
79		query, ok := buildPreviewQuery(w, fields)
80		if !ok {
81			return
82		}
83	
84		result, perr := h.timeline.PreviewAlerts(query)
85		if perr != nil {
86			writePreviewError(w, perr)
87			return
88		}
89	
90		groups := make([]previewGroupDTO, 0, len(result.Groups))
91		for _, group := range result.Groups {
92			windows := make([]previewWindow, len(group.Windows))
93			for i, window := range group.Windows {
94				windows[i] = previewWindow{
95					Since:  utcRFC3339Nano(window.Start),
96					Until:  utcRFC3339Nano(window.End),
97					Count:  window.Count,
98					Status: window.Status,
99				}
100			}
101			alerts := make([]previewAlert, len(group.Alerts))
102			for i, alert := range group.Alerts {
103				dto := previewAlert{TriggeredAt: utcRFC3339Nano(alert.OpenedAt)}
104				if alert.RecoveredAt != nil {
105					recovered := utcRFC3339Nano(*alert.RecoveredAt)
106					dto.RecoveredAt = &recovered
107				}
108				alerts[i] = dto
109			}
110			groups = append(groups, previewGroupDTO{
111				Service:     group.Service,
112				LabelValues: nonNilLabelValues(group.LabelValues),
113				Windows:     windows,
114				Alerts:      alerts,
115			})
116		}
117	
118		names := result.GroupLabelNames
119		if names == nil {
120			names = []string{}
121		}
122		writeJSON(w, http.StatusOK, previewResponse{
123			GroupLabels: names,
124			Groups:      groups,
125		})
126	}
127	
128	// nonNilLabelValues keeps a missing-label null entry but turns a nil (no
129	// group labels) slice into an empty JSON array.
130	func nonNilLabelValues(values []*string) []*string {
131		if values == nil {
132			return []*string{}
133		}
134		return values
135	}
136	
137	// buildPreviewQuery validates the decoded object members and returns the
138	// normalized query. It writes the 400 itself and returns ok=false on any
139	// problem, so callers never produce a partial result.
140	func buildPreviewQuery(w http.ResponseWriter, fields map[string]json.RawMessage) (events.AlertPreviewQuery, bool) {
141		var query events.AlertPreviewQuery
142	
143		parseTime := func(name string) (time.Time, bool) {
144			var text string
145			if !decodeRequired(w, fields, name, &text) {
146				return time.Time{}, false
147			}
148			parsed, err := time.Parse(time.RFC3339Nano, text)
149			if err != nil {
150				writeError(w, http.StatusBadRequest, name+" must be an RFC3339Nano timestamp")
151				return time.Time{}, false
152			}
153			return parsed, true
154		}
155	
156		since, ok := parseTime("since")
157		if !ok {
158			return query, false
159		}
160		until, ok := parseTime("until")
161		if !ok {
162			return query, false
163		}
164		if !until.After(since) {
165			writeError(w, http.StatusBadRequest, "since must be before until")
166			return query, false
167		}
168	
169		var windowSeconds int64
170		if !decodeRequiredInt(w, fields, "window_seconds", &windowSeconds) {
171			return query, false
172		}
173		if windowSeconds < 1 || windowSeconds > 86400 {
174			writeError(w, http.StatusBadRequest, "window_seconds must be an integer from 1 to 86400")
175			return query, false
176		}
177	
178		var threshold int64
179		if !decodeRequiredInt(w, fields, "threshold", &threshold) {
180			return query, false
181		}
182		if threshold < 1 || threshold > 1000000 {
183			writeError(w, http.StatusBadRequest, "threshold must be an integer from 1 to 1000000")
184			return query, false
185		}
186	
187		var triggerWindows int64
188		if !decodeRequiredInt(w, fields, "trigger_windows", &triggerWindows) {
189			return query, false
190		}
191		if triggerWindows < 1 || triggerWindows > 100 {
192			writeError(w, http.StatusBadRequest, "trigger_windows must be an integer from 1 to 100")
193			return query, false
194		}
195	
196		var recoverWindows int64
197		if !decodeRequiredInt(w, fields, "recover_windows", &recoverWindows) {
198			return query, false
199		}
200		if recoverWindows < 1 || recoverWindows > 100 {
201			writeError(w, http.StatusBadRequest, "recover_windows must be an integer from 1 to 100")
202			return query, false
203		}
204		if raw, present := fields["service"]; present {
205			if bytes.Equal(raw, []byte("null")) {
206				writeError(w, http.StatusBadRequest, "service has the wrong type")
207				return query, false
208			}
209			var service string
210			if !decodeRaw(w, raw, "service", &service) {
211				return query, false
212			}
213			query.Service = service
214		}
215		if raw, present := fields["severity"]; present {
216			if bytes.Equal(raw, []byte("null")) {
217				writeError(w, http.StatusBadRequest, "severity has the wrong type")
218				return query, false
219			}
220			var severity string
221			if !decodeRaw(w, raw, "severity", &severity) {
222				return query, false
223			}
224			query.Severity = severity
225		}
226	
227		// labels follows ingestion semantics, where null means "no labels".
228		if raw, present := fields["labels"]; present && !bytes.Equal(raw, []byte("null")) {
229			decoded, lerr := events.DecodeLabelsObject(raw)
230			if lerr != nil {
231				writeError(w, http.StatusBadRequest, "labels must be an object of string values")
232				return query, false
233			}
234			conditions, lerr := events.NormalizeLabelConditions(decoded)
235			if lerr != nil {
236				writeError(w, http.StatusBadRequest, lerr.Error())
237				return query, false
238			}
239			query.Labels = conditions
240		}
241	
242		if raw, present := fields["group_labels"]; present {
243			if bytes.Equal(raw, []byte("null")) {
244				writeError(w, http.StatusBadRequest, "group_labels must be an array of label names")
245				return query, false
246			}
247			var requested []string
248			if err := json.Unmarshal(raw, &requested); err != nil {
249				writeError(w, http.StatusBadRequest, "group_labels must be an array of label names")
250				return query, false
251			}
252			if len(requested) > maxGroupLabels {
253				writeError(w, http.StatusBadRequest, "group_labels may contain at most four names")
254				return query, false
255			}
256			seen := make(map[string]struct{}, len(requested))
257			names := make([]string, 0, len(requested))
258			for _, name := range requested {
259				normalized, gerr := events.NormalizeLabelName(name)
260				if gerr != nil {
261					writeError(w, http.StatusBadRequest, gerr.Error())
262					return query, false
263				}
264				if _, dup := seen[normalized]; dup {
265					writeError(w, http.StatusBadRequest, "group_labels names must not repeat after trimming")
266					return query, false
267				}
268				seen[normalized] = struct{}{}
269				names = append(names, normalized)
270			}
271			query.GroupLabels = names
272		}
273	
274		query.Since = since
275		query.Until = until
276		query.Window = time.Duration(windowSeconds) * time.Second
277		query.Threshold = int(threshold)
278		query.TriggerWindows = int(triggerWindows)
279		query.RecoverWindows = int(recoverWindows)
280		return query, true
281	}
282	
283	// decodeRequired unmarshals one present, non-null member into target. A
284	// missing or null member is reported with the field's name.
285	func decodeRequired(w http.ResponseWriter, fields map[string]json.RawMessage, name string, target any) bool {
286		raw, present := fields[name]
287		if !present || bytes.Equal(raw, []byte("null")) {
288			writeError(w, http.StatusBadRequest, name+" is required")
289			return false
290		}
291		return decodeRaw(w, raw, name, target)
292	}
293	
294	// decodeRequiredInt is decodeRequired for members that must be decimal
295	// integer literals: scientific notation (1e2), fractions (1.0), signs, and
296	// quoted numbers are all a wrong type, matching the query-parameter rules.
297	func decodeRequiredInt(w http.ResponseWriter, fields map[string]json.RawMessage, name string, target *int64) bool {
298		raw, present := fields[name]
299		if !present || bytes.Equal(raw, []byte("null")) {
300			writeError(w, http.StatusBadRequest, name+" is required")
301			return false
302		}
303		if !isDecimal(string(raw)) {
304			writeError(w, http.StatusBadRequest, name+" has the wrong type")
305			return false
306		}
307		if err := json.Unmarshal(raw, target); err != nil {
308			writeError(w, http.StatusBadRequest, name+" has the wrong type")
309			return false
310		}
311		return true
312	}
313	
314	// decodeRaw unmarshals one member, reporting a typed 400 on failure.
315	func decodeRaw(w http.ResponseWriter, raw json.RawMessage, name string, target any) bool {
316		if err := json.Unmarshal(raw, target); err != nil {
317			writeError(w, http.StatusBadRequest, name+" has the wrong type")
318			return false
319		}
320		return true
321	}
322	
323	// decodeStrictObject decodes the outer JSON value, requiring an object with
324	// unique member names drawn from allowed. Syntax errors, non-objects,
325	// trailing tokens, duplicate keys, and unknown fields are all rejected.
326	func decodeStrictObject(body []byte, allowed map[string]struct{}) (map[string]json.RawMessage, error) {
327		dec := json.NewDecoder(bytes.NewReader(body))
328		open, err := dec.Token()
329		if err != nil {
330			return nil, err
331		}
332		if delim, ok := open.(json.Delim); !ok || delim != '{' {
333			return nil, errors.New("body must be a JSON object")
334		}
335		fields := make(map[string]json.RawMessage)
336		for dec.More() {
337			keyToken, err := dec.Token()
338			if err != nil {
339				return nil, err
340			}
341			key, ok := keyToken.(string)
342			if !ok {
343				return nil, errors.New("object keys must be strings")
344			}
345			if _, known := allowed[key]; !known {
346				return nil, errors.New("unknown field " + key)
347			}
348			if _, dup := fields[key]; dup {
349				return nil, errors.New("duplicate field " + key)
350			}
351			var value json.RawMessage
352			if err := dec.Decode(&value); err != nil {
353				return nil, err
354			}
355			fields[key] = value
356		}
357		if _, err := dec.Token(); err != nil {
358			return nil, err
359		}
360		var extra json.RawMessage
361		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
362			if err == nil {
363				return nil, errors.New("unexpected trailing data")
364			}
365			return nil, err
366		}
367		return fields, nil
368	}
369	
370	func writePreviewError(w http.ResponseWriter, err error) {
371		switch {
372		case errors.Is(err, events.ErrAlertRange):
373			writeError(w, http.StatusBadRequest, "since must be before until")
374		case errors.Is(err, events.ErrAlertWindow):
375			writeError(w, http.StatusBadRequest, "window_seconds must be an integer from 1 to 86400")
376		case errors.Is(err, events.ErrAlertThreshold):
377			writeError(w, http.StatusBadRequest, "threshold must be an integer from 1 to 1000000")
378		case errors.Is(err, events.ErrAlertConsecutive):
379			writeError(w, http.StatusBadRequest, "trigger_windows and recover_windows must be integers from 1 to 100")
380		case errors.Is(err, events.ErrAlertGroupLabels):
381			writeError(w, http.StatusBadRequest, "group_labels may contain at most four names")
382		case errors.Is(err, events.ErrAlertTooManyWindows):
383			writeError(w, http.StatusBadRequest, "range must not require more than 10000 windows")
384		case errors.Is(err, events.ErrAlertTooManyGroups):
385			writeError(w, http.StatusBadRequest, "preview must not require more than 100000 group windows")
386		default:
387			writeError(w, http.StatusBadRequest, "invalid alert preview request")
388		}
389	}
