126		dec.DisallowUnknownFields()
127		var input envelope
128		if err := dec.Decode(&input); err != nil {
129			writeError(w, http.StatusBadRequest, "invalid JSON body")
130			return
131		}
132		var extra json.RawMessage
133		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
134			writeError(w, http.StatusBadRequest, "invalid JSON body")
135			return
136		}
137		if len(bytes.TrimSpace(input.Events)) == 0 {
138			writeError(w, http.StatusBadRequest, "events must be a non-empty array")
139			return
140		}
141	
142		batch, err := events.DecodeBatch(input.Events)
143		if err != nil {
144			writeError(w, http.StatusBadRequest, "invalid events array")
145			return
146		}
147		if len(batch) == 0 {
148			writeError(w, http.StatusBadRequest, "events must not be empty")
149			return
150		}
151	
152		result, err := h.timeline.Ingest(batch, h.log.Append)
153		if err != nil {
154			switch {
155			case events.IsValidationError(err):
156				writeError(w, http.StatusBadRequest, err.Error())
157			case events.IsConflictError(err):
158				writeError(w, http.StatusConflict, err.Error())
159			default:
160				writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
161			}
162			return
163		}
164	
165		writeJSON(w, http.StatusOK, map[string]int{
166			"created":  result.Created,
167			"replayed": result.Replayed,
168		})
169	}
170	
171	func (h *Handler) getEvents(w http.ResponseWriter, r *http.Request) {
172		if h.unavailable() {
173			writeError(w, http.StatusServiceUnavailable, "event storage is unavailable; restart required")
174			return
175		}
176	
177		values := r.URL.Query()
178		labels, err := events.ParseLabelConditions(values["label"])
179		if err != nil {
180			writeError(w, http.StatusBadRequest, err.Error())
181			return
182		}
183		query := events.Query{
184			Service:  values.Get("service"),
185			Severity: values.Get("severity"),
186			Labels:   labels,
187		}
188		if raw := values.Get("since"); raw != "" {
189			parsed, err := time.Parse(time.RFC3339Nano, raw)
190			if err != nil {
191				writeError(w, http.StatusBadRequest, "since must be an RFC3339Nano timestamp")
192				return
193			}
194			query.Since = parsed
195		}
196		if raw := values.Get("until"); raw != "" {
197			parsed, err := time.Parse(time.RFC3339Nano, raw)
198			if err != nil {
199				writeError(w, http.StatusBadRequest, "until must be an RFC3339Nano timestamp")
200				return
201			}
202			query.Until = parsed
203		}
204		if !query.Since.IsZero() && !query.Until.IsZero() && query.Since.After(query.Until) {
205			writeError(w, http.StatusBadRequest, "since must not be after until")
206			return
207		}
208	
209		found := h.timeline.Query(query)
210		writeEvents(w, found)
211	}
212	
213	func writeError(w http.ResponseWriter, status int, message string) {
214		writeJSON(w, status, map[string]string{"error": message})
215	}
216	
217	func writeJSON(w http.ResponseWriter, status int, payload any) {
218		w.Header().Set("Content-Type", "application/json")
219		w.WriteHeader(status)
220		enc := json.NewEncoder(w)
221		_ = enc.Encode(payload)
222	}
223	
224	func writeEvents(w http.ResponseWriter, found []events.Event) {
225		w.Header().Set("Content-Type", "application/json")
226		w.WriteHeader(http.StatusOK)
227		if len(found) == 0 {
228			_, _ = w.Write([]byte("[]\n"))
229			return
230		}
231		if err := json.NewEncoder(w).Encode(eventsToDTOs(found)); err != nil {
232			return
233		}
234	}
235	
236	type eventDTO struct {
237		ID       string            `json:"id"`
238		Service  string            `json:"service"`
239		Severity string            `json:"severity"`
240		Message  string            `json:"message"`
241		At       time.Time         `json:"at"`
242		Labels   map[string]string `json:"labels,omitempty"`
243	}
244	
245	func eventsToDTOs(found []events.Event) []eventDTO {
246		dtos := make([]eventDTO, len(found))
247		for i, event := range found {
248			dtos[i] = eventDTO{
249				ID:       event.ID,
250				Service:  event.Service,
251				Severity: event.Severity,
252				Message:  event.Message,
253				At:       event.At,
254				Labels:   event.Labels,
255			}
256		}
257		return dtos
258	}
